import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { 
  SunIcon, 
  MoonIcon, 
  MenuIcon, 
  XIcon,
  SparklesIcon,
  StarIcon
} from '@heroicons/react/24/outline';

const Navbar = () => {
  const { user, logout } = useAuth();
  const { darkMode, toggleTheme } = useTheme();
  const navigate = useNavigate();
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
    setIsMenuOpen(false);
  };

  return (
    <nav className="bg-white/30 dark:bg-dark-200/30 backdrop-blur-md border-b border-fun-purple/20 shadow-glow transition-all duration-300">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16">
          <div className="flex items-center">
            <Link
              to="/"
              className="fun-title flex items-center text-2xl font-bold hover:scale-105 transition-all duration-300"
            >
              <SparklesIcon className="h-8 w-8 mr-2 animate-spin-slow text-fun-purple" />
              ✨ Magic Clipboard
            </Link>
          </div>

          {/* Desktop menu */}
          <div className="hidden sm:flex items-center space-x-4">
            <button
              onClick={toggleTheme}
              className="fun-button !bg-gradient-sunset p-2 rounded-full hover:shadow-neon focus:outline-none transition-all duration-300"
              aria-label="Toggle dark mode"
            >
              {darkMode ? (
                <SunIcon className="h-6 w-6 animate-pulse-fast" />
              ) : (
                <MoonIcon className="h-6 w-6 animate-pulse-fast" />
              )}
            </button>

            {user ? (
              <div className="flex items-center space-x-4">
                {user.isAdmin && (
                  <Link
                    to="/admin"
                    className="fun-button !bg-gradient-party animate-party"
                  >
                    <StarIcon className="h-5 w-5 mr-1 animate-spin-slow" />
                    Magic Admin ✨
                  </Link>
                )}
                <button
                  onClick={handleLogout}
                  className="fun-button"
                >
                  Goodbye 👋
                </button>
              </div>
            ) : (
              <Link
                to="/login"
                className="fun-button animate-float"
              >
                Enter Magic Portal ✨
              </Link>
            )}
          </div>

          {/* Mobile menu button */}
          <div className="flex items-center sm:hidden">
            <button
              onClick={toggleTheme}
              className="fun-button !bg-gradient-sunset p-2 rounded-full hover:shadow-neon focus:outline-none"
              aria-label="Toggle dark mode"
            >
              {darkMode ? (
                <SunIcon className="h-6 w-6 animate-pulse-fast" />
              ) : (
                <MoonIcon className="h-6 w-6 animate-pulse-fast" />
              )}
            </button>
            <button
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className="fun-button ml-2 p-2 rounded-full hover:shadow-neon focus:outline-none"
            >
              {isMenuOpen ? (
                <XIcon className="h-6 w-6 animate-wiggle" />
              ) : (
                <MenuIcon className="h-6 w-6 animate-pulse-fast" />
              )}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile menu */}
      {isMenuOpen && (
        <div className="sm:hidden bg-white/30 dark:bg-dark-200/30 backdrop-blur-md border-t border-fun-purple/20">
          <div className="px-2 pt-2 pb-3 space-y-1">
            {user ? (
              <>
                {user.isAdmin && (
                  <Link
                    to="/admin"
                    onClick={() => setIsMenuOpen(false)}
                    className="fun-button !bg-gradient-party animate-party block w-full text-center mb-2"
                  >
                    <StarIcon className="h-5 w-5 inline mr-1 animate-spin-slow" />
                    Magic Admin ✨
                  </Link>
                )}
                <button
                  onClick={handleLogout}
                  className="fun-button block w-full"
                >
                  Goodbye 👋
                </button>
              </>
            ) : (
              <Link
                to="/login"
                onClick={() => setIsMenuOpen(false)}
                className="fun-button animate-float block w-full text-center"
              >
                Enter Magic Portal ✨
              </Link>
            )}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;
